import{_ as a,o as t,c as i,ag as o}from"./chunks/framework.DaCm-iTo.js";const m=JSON.parse('{"title":"EmakiCoreLib","description":"","frontmatter":{},"headers":[],"relativePath":"modules/corelib/index.md","filePath":"modules/corelib/index.md","lastUpdated":null}'),r={name:"modules/corelib/index.md"};function l(d,e,n,c,s,h){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="emakicorelib" tabindex="-1">EmakiCoreLib <a class="header-anchor" href="#emakicorelib" aria-label="Permalink to &quot;EmakiCoreLib&quot;">​</a></h1><p>EmakiCoreLib 是 Emaki 系列所有业务插件的共享运行时核心。它本身不提供完整玩法循环，而是提供跨插件复用的底层能力：动作系统、GUI 模板、物品来源、PDC、物品装配、条件、表达式、经济、权重、调度兼容和 bStats 托管。</p><blockquote><p>分区原则：这里记录“所有插件都能复用”的能力。Attribute、Forge、Strengthen、Cooking、Gem、Skills、Item、Level 等插件自己注册的动作、API、配置字段和玩法流程，放在对应插件文档中说明。</p></blockquote><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td>模块版本</td><td><code>4.6.9</code></td></tr><tr><td>API Jar</td><td><code>emaki-corelib-api-4.6.9.jar</code></td></tr><tr><td>插件本体</td><td><code>EmakiCoreLib-4.6.9.jar</code></td></tr><tr><td>主类</td><td><code>emaki.jiuwu.craft.corelib.EmakiCoreLibPlugin</code></td></tr><tr><td>Java</td><td><code>25</code></td></tr><tr><td>Paper API</td><td><code>1.21.8-R0.1-SNAPSHOT</code></td></tr><tr><td>paper-plugin.yml api-version</td><td><code>1.21.8</code></td></tr><tr><td>folia-supported</td><td><code>true</code></td></tr><tr><td>硬依赖</td><td>无</td></tr><tr><td>软依赖</td><td>Vault、ExcellentEconomy、PlaceholderAPI、MMOItems、MythicMobs、ItemsAdder、Nexo、Oraxen、EcoItems、NeigeItems、CraftEngine、PacketEvents</td></tr><tr><td>主命令</td><td><code>/emakicorelib</code>（别名 <code>/corelib</code>、<code>/emakicore</code>）</td></tr><tr><td>权限</td><td><code>emakicorelib.admin</code>、<code>emakicorelib.reload</code></td></tr></tbody></table><p>CoreLib 必须先加载。业务插件依赖它提供的共享服务；如果 CoreLib 启动失败，应先修复 CoreLib，再排查其他模块。</p><h2 id="运行兼容性" tabindex="-1">运行兼容性 <a class="header-anchor" href="#运行兼容性" aria-label="Permalink to &quot;运行兼容性&quot;">​</a></h2><p>CoreLib 在启动时输出兼容性报告：Java 25、Paper/Folia 能力缺失会阻止启动；Minecraft 版本低于 <code>1.21.8</code>、无法识别，或达到 <code>1.22.0</code> 及以上时会标记为“未验证”并输出告警，而不会依赖猜测的版本白名单强制拦截。<code>EmakiCoreLibApi.compatibilityReport()</code> 可供依赖插件读取该报告。</p><h2 id="安装边界" tabindex="-1">安装边界 <a class="header-anchor" href="#安装边界" aria-label="Permalink to &quot;安装边界&quot;">​</a></h2><p>服务器只安装插件本体 Jar：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/</span></span>
<span class="line"><span>├── EmakiCoreLib-4.6.9.jar</span></span>
<span class="line"><span>└── EmakiAttribute-4.6.9.jar / EmakiForge-4.6.4.jar / ...</span></span></code></pre></div><p>不要把 <code>emaki-corelib-api-*.jar</code> 放进服务器 <code>plugins/</code>。API Jar 只给第三方开发者作为 Maven <code>provided</code> 或 Gradle <code>compileOnly</code> 编译依赖使用。</p><h2 id="corelib-提供什么" tabindex="-1">CoreLib 提供什么 <a class="header-anchor" href="#corelib-提供什么" aria-label="Permalink to &quot;CoreLib 提供什么&quot;">​</a></h2><h3 id="通用动作系统" tabindex="-1">通用动作系统 <a class="header-anchor" href="#通用动作系统" aria-label="Permalink to &quot;通用动作系统&quot;">​</a></h3><p>动作系统允许各插件在 YAML 中执行消息、音效、粒子、命令、经济、经验、临时物品、方块、传送和动作模板。动作语法、控制前缀、CoreLib 内置动作，以及 <code>/corelib action list|run</code> 管理命令见 <a href="./actions.html">动作系统</a>。</p><p>业务插件可以向同一个注册表追加自己的动作。例如 Level 的等级经验动作、Attribute 的属性动作、Skills 的技能动作都应在对应插件页面中查参数，不再集中塞在 CoreLib 页面里。</p><h3 id="gui-系统" tabindex="-1">GUI 系统 <a class="header-anchor" href="#gui-系统" aria-label="Permalink to &quot;GUI 系统&quot;">​</a></h3><p>GUI 系统提供菜单模板、槽位解析、按钮、点击处理、会话管理、物品来源解析和动态渲染基础。业务插件只声明自己的 GUI 文件与流程逻辑。详情见 <a href="./gui.html">GUI 系统</a>。</p><h3 id="物品来源" tabindex="-1">物品来源 <a class="header-anchor" href="#物品来源" aria-label="Permalink to &quot;物品来源&quot;">​</a></h3><p>物品来源系统统一解析 Vanilla、CraftEngine、ItemsAdder、Nexo、Oraxen、EcoItems、MMOItems、NeigeItems、EmakiItem 等来源，让配方、材料、奖励和 GUI 槽位不依赖显示名或 Lore。详情见 <a href="./item-source.html">物品来源系统</a>。</p><h3 id="pdc-与物品装配" tabindex="-1">PDC 与物品装配 <a class="header-anchor" href="#pdc-与物品装配" aria-label="Permalink to &quot;PDC 与物品装配&quot;">​</a></h3><p>CoreLib 统一封装 Bukkit PersistentDataContainer，并通过 Assembly 把不同模块写入的 layer 合成为最终名称和 Lore。Forge、Strengthen、Gem、Item、Attribute 等模块都通过这条链路避免互相覆盖展示。详情见 <a href="./pdc.html">PDC 服务</a>、<a href="./assembly.html">物品装配系统</a> 和 <a href="./structured-presentation.html">名称与 Lore 操作</a>。</p><h3 id="共享玩法事件" tabindex="-1">共享玩法事件 <a class="header-anchor" href="#共享玩法事件" aria-label="Permalink to &quot;共享玩法事件&quot;">​</a></h3><p>CoreLib 会把部分 Bukkit / MythicMobs 玩法事件统一归一成配置用的事件 ID，供 EmakiLevel 的经验来源和 EmakiCodex 的成就触发器复用。可填写的 ID 与变量见 <a href="./gameplay-events.html">共享玩法事件 ID</a>。</p><h3 id="条件、表达式、经济和权重" tabindex="-1">条件、表达式、经济和权重 <a class="header-anchor" href="#条件、表达式、经济和权重" aria-label="Permalink to &quot;条件、表达式、经济和权重&quot;">​</a></h3><ul><li><a href="./condition.html">条件系统</a>：通用条件表达与条件组。</li><li><a href="./expression.html">表达式引擎</a>：费用、概率、等级、伤害和配置公式。</li><li><a href="./economy.html">经济桥接</a>：Vault / ExcellentEconomy provider 与动态枚举。</li><li><a href="./weight.html">权重系统</a>：随机池、品质池、奖励池和保底池的通用工具。</li></ul><h2 id="推荐阅读顺序" tabindex="-1">推荐阅读顺序 <a class="header-anchor" href="#推荐阅读顺序" aria-label="Permalink to &quot;推荐阅读顺序&quot;">​</a></h2><h3 id="服主-配置维护者" tabindex="-1">服主 / 配置维护者 <a class="header-anchor" href="#服主-配置维护者" aria-label="Permalink to &quot;服主 / 配置维护者&quot;">​</a></h3><ol><li><a href="./item-source.html">物品来源系统</a>：先学会如何稳定引用材料和奖励。</li><li><a href="./actions.html">动作系统</a>：掌握成功、失败、奖励和提示写法。</li><li><a href="./condition.html">条件系统</a>：配置权限、物品、状态和表达式判断。</li><li><a href="./expression.html">表达式引擎</a>：编写费用、概率和数值公式。</li><li><a href="./gui.html">GUI 系统</a>：调整菜单布局和按钮交互。</li><li>对应业务插件页面：配置真正的玩法流程。</li></ol><h3 id="第三方开发者" tabindex="-1">第三方开发者 <a class="header-anchor" href="#第三方开发者" aria-label="Permalink to &quot;第三方开发者&quot;">​</a></h3><ol><li><a href="./pdc.html">PDC 服务</a>：了解共享数据写入边界。</li><li><a href="./assembly.html">物品装配系统</a>：了解多模块展示合并规则。</li><li>对应插件 [API 与集成] 页面：调用业务 API，不依赖实现类。</li></ol><h2 id="默认配置目录" tabindex="-1">默认配置目录 <a class="header-anchor" href="#默认配置目录" aria-label="Permalink to &quot;默认配置目录&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/EmakiCoreLib/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>└── lang/</span></span>
<span class="line"><span>    ├── zh_CN.yml</span></span>
<span class="line"><span>    └── en_US.yml</span></span></code></pre></div><p><code>config.yml</code> 管理语言、GUI 后端、共享玩法事件、动作循环与动作模板，以及全局 Debug；将 <code>debug.global_all</code> 设为 <code>true</code> 会为所有使用 CoreLib <code>DebugLogger</code> 的 Emaki 模块输出 Debug 日志。管理员也可用 <code>/corelib debug all on|off|status</code> 临时切换，CoreLib 重载后会重新采用配置值。<code>lang/</code> 管理 CoreLib 自身消息。业务插件会生成自己的配置目录，不建议把业务配置混放进 CoreLib。</p>`,34)])])}const b=a(r,[["render",l]]);export{m as __pageData,b as default};
